params.command:
$ErrorActionPreference='Stop'
$path='C:\HeavenServices\services.json'
$backup='C:\HeavenServices\backups\services.pre-worker-fabric-repair-20260929.json'
Copy-Item $path $backup -Force

$current=@(Get-Content $path -Raw | ConvertFrom-Json)
$flat=New-Object System.Collections.Generic.List[object]
foreach($item in $current){
  if($null -ne $item.name){
    $flat.Add($item)
    continue
  }
  if($null -ne $item.value){
    foreach($child in @($item.value)){
      if($null -ne $child.name){ $flat.Add($child) }
    }
  }
}
$flat=@($flat | Where-Object {$_.name -ne 'Heaven Worker Fabric'})
$entry=[pscustomobject]@{
  name='Heaven Worker Fabric'
  category='isolated local workers'
  version='heaven/worker-node22:2026.09'
  install_method='Docker Compose in Ubuntu WSL2'
  executable_container='heaven-worker-01..08'
  URL=''
  host='Docker bridge only'
  port=0
  healthcheck='Docker healthcheck: Node + Python + Git'
  startup_mechanism='base 01-04: Docker restart unless-stopped; burst 05-08: opt-in'
  data_path='Docker named volumes; C:\HeavenServices\worker-fabric\shared; C:\HeavenServices\worker-fabric\artifacts'
  config_path='C:\HeavenServices\worker-fabric\docker-compose.yml'
  update_command='powershell -File C:\HeavenServices\scripts\heaven-workers.ps1 BUILD'
  enabled=$true
  notes='4 healthy base workers at 4 CPU/2 GiB each; 4 verified burst workers at 2 CPU/1 GiB each; no published ports; no host credential mounts'
}
$flat += $entry
[IO.File]::WriteAllText($path,($flat | ConvertTo-Json -Depth 8),(New-Object Text.UTF8Encoding($true)))

$verify=Get-Content $path -Raw | ConvertFrom-Json
$names=@($verify | ForEach-Object {$_.name})
$wf=@($verify | Where-Object {$_.name -eq 'Heaven Worker Fabric'})
if(@($verify).Count -ne 21){throw "Expected 21 registry entries; got $(@($verify).Count)"}
if($wf.Count -ne 1){throw "Expected one Worker Fabric entry; got $($wf.Count)"}
if($names -contains $null){throw 'Registry still contains unnamed wrapper objects'}
[pscustomobject]@{count=@($verify).Count;workerFabric=$wf[0].name;allNamed=($names -notcontains $null);backup=$backup} | ConvertTo-Json -Compress
